import{_ as i,b as o,c as l,g as r}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"一阶逻辑","description":"","frontmatter":{"title":"一阶逻辑","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/8.md","filePath":"articles/ai/books/ai-modern-approach/8.md"}'),a={name:"articles/ai/books/ai-modern-approach/8.md"};function s(n,t,e,d,g,_){return o(),l("div",null,[...t[0]||(t[0]=[r('<p>第 8 章从命题逻辑扩展到一阶逻辑，核心是表达对象、关系和量词的能力。重点包括：</p><h2 id="一阶逻辑语言" tabindex="-1">一阶逻辑语言</h2><ul><li><strong>常量、变量、谓词、函数、量词</strong>（∀, ∃）</li><li><strong>语法</strong>：项、原子、复合公式</li><li><strong>语义</strong>：解释、模型、真值赋值</li></ul><h2 id="知识表示示例" tabindex="-1">知识表示示例</h2><ul><li>家族关系、数字系统、集合论</li><li>Wumpus 世界的一阶描述</li></ul><h2 id="推理" tabindex="-1">推理</h2><ul><li><strong>命题化（避免过度）</strong>：将包含量词的公式转换为命题逻辑实例（如具象化）</li><li><strong>合一</strong>：寻找变量替换使两个表达式相同，是推理的基础</li><li><strong>前向链接</strong>：从事实出发，用规则（∀ 蕴含）生成新事实，需合一匹配</li><li><strong>反向链接</strong>：目标驱动，递归证明子目标</li><li><strong>归结</strong>：一阶逻辑的归结需合一，比命题归结复杂</li></ul><h2 id="归纳" tabindex="-1">归纳</h2><ul><li>归纳原理（自然数归纳、结构归纳）</li></ul><h2 id="类别与对象" tabindex="-1">类别与对象</h2><ul><li>用谓词表示类别（如 Dog(x)）、属性（Color(x, Brown)）、关系（HasParent(x, y)）</li><li><strong>本体论</strong>：描述世界中对象类型及其关系</li></ul>',11)])])}const u=i(a,[["render",s]]);export{c as __pageData,u as default};
